bounded_host_request.command:
set -eu
root="$(git rev-parse --show-toplevel)"
test "$(realpath "$root")" = /home/gace/Project/Gserver/projects/TGtumbler/GateApp-Bot || exit 70
c="$(docker ps --filter label=com.docker.compose.service=gaybbs --format '{{.ID}}')"
test "$(printf '%s\n' "$c" | sed '/^$/d' | wc -l)" -eq 1 || exit 71
docker exec "$c" node --import /app/preload/telegram-ipv4-preload.mjs --input-type=module -e '
import {readFileSync} from "node:fs";
const token=readFileSync("/run/secrets/bot_token","utf8").trim();
const targets=[
 ["operator","/run/secrets/bug_report_recipient"],
 ["userbot","/run/secrets/bug_report_userbot_account"]
];
for(const [name,path] of targets){
 const id=readFileSync(path,"utf8").trim();
 if(!/^[1-9][0-9]{4,18}$/.test(id))process.exit(name==="operator"?72:73);
 const result=await fetch("https://api.telegram.org/bot"+token+"/sendMessage",{
  method:"POST",headers:{"Content-Type":"application/json"},
  body:JSON.stringify({chat_id:id,text:"🐞 不具合報告通知・本番接続テスト（実際の不具合報告ではありません）"})
 });
 const data=await result.json();
 if(!result.ok||!data.ok||!Number.isInteger(data.result?.message_id)){
  console.log("REPORT_TEST_"+name.toUpperCase()+"=FAILED");
  process.exit(name==="operator"?74:75);
 }
 console.log("REPORT_TEST_"+name.toUpperCase()+"=TELEGRAM_ACCEPTED");
}
' || exit 76
systemctl --user is-active --quiet gace-userbot-verify.service || exit 77
echo DUAL_TARGET_BOT_API_TEST_PASS
